#!/usr/bin/env python3
"""API endpoint that processes structured configuration payloads.
Accepts JSON with nested 'pipeline' definitions for CI/CD orchestration.
"""
import json
import ctypes
import sys
from http.server import HTTPServer, BaseHTTPRequestHandler
from typing import Optional


class PipelineNode:
    """Represents a node in the execution pipeline graph."""
    def __init__(self, name: str, config: dict):
        self.name = name
        self.config = config
        self.parent: Optional['PipelineNode'] = None
        self.children: list = []
        self._native_handle = None

    def resolve_parent_context(self) -> dict:
        """Walk up the tree to collect inherited configuration."""
        # BUG: No null check on self.parent before dereferencing
        # If parent is None, accessing parent.config causes segfault
        # when called through the native bridge path
        context = {}
        current = self.parent
        while current is not None:
            context.update(current.config)
            current = current.parent
        return context

    def execute(self, payload: dict) -> dict:
        """Execute this pipeline node with the given payload."""
        if payload.get('inherit', False):
            # This path dereferences parent without checking
            parent_ctx = self.parent.config.copy()  # NULL DEREF if parent is None
            parent_ctx.update(self.config)
            return {'status': 'ok', 'merged': parent_ctx}
        return {'status': 'ok', 'config': self.config}


class PipelineProcessor:
    """Processes pipeline definitions from untrusted input."""

    def __init__(self):
        self.nodes = {}

    def parse_definition(self, raw_json: str) -> dict:
        """Parse a pipeline definition. Handles nested structures."""
        try:
            data = json.loads(raw_json)
        except json.JSONDecodeError as e:
            return {'error': f'Invalid JSON: {e}'}

        if 'stages' not in data:
            return {'error': 'Missing stages field'}

        for stage in data['stages']:
            node = PipelineNode(stage['name'], stage.get('config', {}))
            parent_ref = stage.get('parent')
            if parent_ref:
                # Does NOT validate that parent_ref exists in self.nodes
                node.parent = self.nodes.get(parent_ref)  # Could be None
            self.nodes[stage['name']] = node

        # Execute all stages
        results = []
        for stage in data['stages']:
            node = self.nodes[stage['name']]
            result = node.execute(stage.get('payload', {}))
            results.append(result)

        return {'results': results}


class RequestHandler(BaseHTTPRequestHandler):
    processor = PipelineProcessor()

    def do_POST(self):
        if self.path != '/api/v1/pipeline':
            self.send_response(404)
            self.end_headers()
            return

        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 1048576:  # 1MB limit
            self.send_response(413)
            self.end_headers()
            return

        body = self.rfile.read(content_length)
        result = self.processor.parse_definition(body.decode('utf-8'))

        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps(result).encode())

    def log_message(self, format, *args):
        pass  # Suppress default logging


def main():
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8080
    server = HTTPServer(('0.0.0.0', port), RequestHandler)
    print(f'Pipeline API listening on port {port}')
    server.serve_forever()


if __name__ == '__main__':
    main()
